const c=document.querySelector('canvas'),x=c.getContext('2d'),image=new Image(),q=s=>document.querySelector(s);let ready=false,playing=false,elapsed=0,previous=0,wait=0;const duration=3.2;
// Nonuniform exposures emphasize anticipation, contact and recovery.
const boundaries=[0,.22,.4,.56,.74,.84,.96,1.09,1.23,1.45,1.65,1.85,2.06,2.32,2.58,2.86,3.2];
function frameIndex(){for(let i=0;i<16;i++)if(elapsed<boundaries[i+1])return i;return 15}
function draw(){x.setTransform(1.2,0,0,1.2,0,0);x.clearRect(0,0,1000,480);let i=frameIndex(),impact=elapsed>=1.09&&elapsed<1.45;let strength=q('#shake').checked&&impact?2.4:0;x.save();x.translate(strength*Math.sin(elapsed*160),strength*Math.cos(elapsed*130));
// Simple environment kept separate from the atlas.
x.fillStyle='#23383d';for(let k=0;k<10;k++){x.fillRect(k*120-30,150,5,170);x.fillRect(k*120-40,150,25,9)}
x.fillStyle='#334743';x.beginPath();x.moveTo(0,351);x.lineTo(1000,351);x.lineTo(1000,480);x.lineTo(0,480);x.fill();x.strokeStyle='#6f80714a';x.lineWidth=1;for(let j=0;j<6;j++){let yy=352+j*j*5;x.beginPath();x.moveTo(0,yy);x.lineTo(1000,yy);x.stroke()}for(let k=0;k<12;k++){x.beginPath();x.moveTo(500+(k-6)*64,351);x.lineTo(500+(k-6)*140,480);x.stroke()}
x.fillStyle='#0b171b55';x.beginPath();x.ellipse(193,375,65,12,0,0,7);x.ellipse(784,375,63,13,0,0,7);x.fill();if(ready){const sw=image.naturalWidth/4,sh=image.naturalHeight/4;let col=i%4,row=Math.floor(i/4);x.drawImage(image,col*sw,row*sh,sw,sh,100,20,800,400)}x.restore();q('#scrub').value=Math.round(elapsed*1000);q('#clock').textContent=elapsed.toFixed(2)+' / 3.20 秒 · '+(i+1)+'/16格';let stage=i<4?0:i<7?1:i<12?2:3;q('#stage').textContent=['蓄力 · 抬杖聚焰','噴發 · 前推施法','命中 · 爆焰與受擊','消散 · 收招與煙塵'][stage];document.querySelectorAll('.stages span').forEach((e,j)=>e.classList.toggle('on',j===stage));q('#play').textContent=playing?'暫停':'播放攻擊';}
image.onload=()=>{ready=true;document.querySelectorAll('button').forEach(b=>b.disabled=false);draw()};image.onerror=()=>q('#stage').textContent='素材載入失敗，請重新整理';image.src='assets/flame-sequence.png';
q('#play').onclick=()=>{if(elapsed>=duration){elapsed=0;wait=0}playing=!playing;draw()};q('#reset').onclick=()=>{elapsed=0;wait=0;playing=false;draw()};q('#step').onclick=()=>{playing=false;elapsed=boundaries[(frameIndex()+1)%16];draw()};q('#scrub').oninput=()=>{playing=false;elapsed=+q('#scrub').value/1000;wait=0;draw()};q('#shake').onchange=draw;
function tick(t){let dt=Math.min((t-previous)/1000||0,.08);previous=t;if(playing&&ready){if(elapsed<duration)elapsed=Math.min(duration,elapsed+dt*(+q('#speed').value));else if(q('#loop').checked){wait+=dt;if(wait>.65){elapsed=0;wait=0}}else playing=false;draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);
